// Üretilen dosya: tool/ozgun/uret.py. İstatistik ve Veri Bilimi · Olasılık dağılımları: binom, normal, Poisson (kolay).
const ozStatistics8Kolay = <(String, String, List<String>, String)>[
  ('X ~ Binom(n, p) ise başarısızlık sayısı n − X\'in varyansı ile X\'in varyansı arasındaki ilişki nedir?', 'Birbirine eşittir', ['n − X\'in varyansı daha büyüktür', 'n − X\'in varyansı n · Var(X)\'tir', 'Toplamları n\'ye eşittir'], 'Var(n − X) = (−1)² Var(X) = Var(X)\'tir; sabitten çıkarma yayılımı değiştirmez. Nitekim np(1 − p) ifadesi p ile 1 − p\'ye göre simetriktir.'),
  ('X ~ Binom(n, p) için P(X = n) neye eşittir?', 'pⁿ', ['n·p', '1 − (1 − p)ⁿ', '(1 − p)ⁿ'], 'Bütün n denemenin başarılı olması gerekir; bağımsızlık nedeniyle olasılık pⁿ\'dir.'),
  ('X ~ Binom(n, p) için P(X ≥ 1) değerini hesaplamanın en kısa yolu hangisidir?', '1 − (1 − p)ⁿ işlemini yapmak', ['n·p çarpımını almak', 'pⁿ değerini bulmak', 'P(X = 1) değerini ikiyle çarpmak'], 'En az bir başarının tümleyeni hiç başarı olmamasıdır; P(X = 0) = (1 − p)ⁿ olduğundan sonuç 1 − (1 − p)ⁿ\'dir.'),
  ('Bir mahkemede 12 jüri üyesinin her biri bağımsız olarak 0,8 olasılıkla doğru karar veriyor. Doğru karar veren üye sayısının dağılımı nedir?', 'Binom(12; 0,8)', ['Poisson(9,6)', 'Binom(0,8; 12)', 'Normal(12; 0,8)'], 'Sabit sayıda (12) bağımsız ve aynı olasılıklı denemedeki başarı sayısı Binom(n = 12, p = 0,8) dağılır.'),
  ('Hilesiz bir zar 60 kez atılıyor. 6 gelme sayısının beklenen değeri kaçtır?', '10', ['6', '12', '15'], 'Beklenen değer np = 60 · (1/6) = 10\'dur.'),
  ('Hilesiz bir para 400 kez atılıyor. Yazı sayısının standart sapması kaçtır?', '10', ['20', '100', '5'], 'Varyans np(1 − p) = 400 · 0,25 = 100, standart sapma √100 = 10\'dur.'),
  ('X ~ Binom(n; 0,5) ve P(X = 0) = 1/32 ise n kaçtır?', '5', ['4', '6', '32'], 'P(X = 0) = (1/2)ⁿ = 1/32 = (1/2)⁵ olduğundan n = 5\'tir.'),
  ('Bir binom dağılımında n = 25 ve beklenen değer 15\'tir. Varyans kaçtır?', '6', ['9', '15', '3,75'], 'p = 15/25 = 0,6 olur; Var = 25 · 0,6 · 0,4 = 6\'dır.'),
  ('p ≠ 0,5 sabit tutularak binom dağılımında n artırıldığında çarpıklık nasıl değişir?', 'Mutlak değeri küçülür, dağılım simetriye yaklaşır', ['Mutlak değeri büyür ve dağılım daha çarpık olur', 'Hiç değişmez', 'İşaret değiştirir'], 'Çarpıklık (1 − 2p)/√(np(1 − p)) paydasında √n bulunduğundan n büyüdükçe sıfıra yaklaşır.'),
  ('X ~ Binom(n, p) ise başarısızlık sayısı n − X hangi dağılıma uyar?', 'Binom(n, 1 − p)', ['Binom(n, p)', 'Binom(n − 1, p)', 'Poisson(n(1 − p))'], 'Her denemede başarısızlık olasılığı 1 − p\'dir ve denemeler bağımsızdır; başarısızlık sayısı Binom(n, 1 − p) olur.'),
  ('Binom olasılıklarının P(X = 0) + … + P(X = n) toplamının 1 olduğu hangi matematiksel sonuçla gösterilir?', 'Binom açılımı: (p + (1 − p))ⁿ = 1', ['Merkezî limit teoremi', 'Büyük sayılar yasası ve olasılık aksiyomları', 'Bayes teoremi'], 'Binom teoremine göre Σ C(n,k)pᵏ(1 − p)ⁿ⁻ᵏ = (p + 1 − p)ⁿ = 1ⁿ = 1\'dir.'),
  ('Bir zar 10 kez atılıyor ve her atışta gelen sayının kendisi kaydediliyor. Toplam sonucun binom modeliyle incelenememesinin nedeni nedir?', 'Her denemenin sonucu iki değil altı kategorilidir', ['Atışlar birbirine bağlıdır', 'Atış sayısı önceden sabitlenmemiş ve değişkendir', 'Olasılıklar atıştan atışa değişir'], 'Binomda her deneme başarı ya da başarısızlık olarak iki sonuçludur. Gelen sayının kendisi altı değerli olduğundan doğrudan binom kurulamaz; ancak \'6 gelmesi\' gibi iki sonuçlu bir olay tanımlanırsa binom olur.'),
  ('X ~ Binom(n, p) iken başarı oranı p̂ = X/n\'nin beklenen değeri nedir?', 'p', ['np', 'p/n', 'p(1 − p)'], 'E(X/n) = E(X)/n = np/n = p\'dir; yani örneklem oranı p için yansız bir tahmin edicidir.'),
  ('Bir olay gerçekleşince 1, gerçekleşmezse 0 değerini alan değişkene ne ad verilir?', 'Göstergesel (indikatör) değişken', ['Sürekli değişken', 'Sıralı (ordinal) kategorik değişken', 'Standart normal değişken'], 'Göstergesel değişken bir olayın gerçekleşip gerçekleşmediğini 1/0 ile kodlar; beklenen değeri olayın olasılığına eşittir.'),
  ('Binom dağılımlı bir X değişkeninin, n tane bağımsız Bernoulli değişkeninin toplamı olarak yazılması hangi sonucu doğrudan verir?', 'E(X) = np ve Var(X) = np(1 − p)', ['X\'in her zaman simetrik olduğunu', 'X\'in sürekli olduğunu', 'P(X = k)\'nin k\'den bağımsız olduğunu'], 'Her Bernoulli değişkeninin ortalaması p, varyansı p(1 − p)\'dir; bağımsız toplamda ortalamalar ve varyanslar toplanarak np ve np(1 − p) elde edilir.'),
  ('Bir partiye katılan 30 kişiden her biri bağımsız olarak 1/365 olasılıkla bugün doğmuştur. Bugün doğan kişi sayısının beklenen değeri yaklaşık kaçtır?', '0,082', ['0,030', '1,000', '0,365'], 'Göstergesel değişkenlerin toplamının beklenen değeri np = 30/365 ≈ 0,082\'dir.'),
  ('Bir Bernoulli değişkeninin varyansı 0,16\'dır. Başarı olasılığı p\'nin alabileceği değerler hangileridir?', '0,2 ya da 0,8', ['Yalnız 0,4', '0,16 ya da 0,84', 'Yalnız 0,5'], 'p(1 − p) = 0,16 denkleminin kökleri p = 0,2 ve p = 0,8\'dir.'),
  ('Bağımsız denemelerde r. başarının elde edilmesi için gereken deneme sayısını modelleyen dağılım hangisidir?', 'Negatif binom dağılımı', ['Hipergeometrik dağılım', 'Multinom (çok kategorili) dağılım', 'Poisson dağılımı'], 'Negatif binom (Pascal) dağılımı sabit sayıda başarıya ulaşana kadar geçen deneme sayısını modeller; r = 1 durumu geometrik dağılımdır.'),
  ('r. başarıya kadarki deneme sayısını gösteren negatif binom değişkeni, hangi değişkenlerin toplamı olarak düşünülebilir?', 'r tane bağımsız geometrik değişkenin', ['r tane bağımsız Poisson değişkeninin', 'r tane bağımsız normal değişkenin', 'r tane bağımsız hipergeometrik değişkenin'], 'Her başarıdan sonraki başarıya kadar geçen deneme sayısı geometriktir; r bekleme süresinin toplamı negatif binom verir.'),
  ('Sayım verisinde varyans ortalamadan belirgin biçimde büyük olduğunda Poisson modeli yerine sıklıkla hangi dağılım kullanılır?', 'Negatif binom dağılımı', ['Binom dağılımı', 'Kesikli düzgün dağılım', 'Hipergeometrik dağılım'], 'Negatif binomun varyansı ortalamasından büyüktür; bu nedenle aşırı yayılımlı (overdispersed) sayım verisi için Poisson\'a yaygın bir seçenektir.'),
  ('Başarı olasılığı 0,2 olan bağımsız denemelerde ilk başarıya kadar geçen deneme sayısının beklenen değeri kaçtır?', '5', ['4', '0,2', '8'], 'Geometrik dağılımda beklenen deneme sayısı 1/p = 1/0,2 = 5\'tir.'),
  ('Normal dağılımlar ailesinde her üye, standart normal Z\'nin X = μ + σZ biçiminde kaydırılıp ölçeklenmesiyle elde edilir. Bu tür dağılım ailelerine ne ad verilir?', 'Konum-ölçek ailesi', ['Üstel aile karışımı', 'Kesikli dağılım ailesi', 'Simetrik olmayan aile'], 'Konum parametresi (μ) eğriyi kaydırır, ölçek parametresi (σ) yayar; tek bir standart biçimden bütün üyeler türetilir. Bu yüzden tek bir Φ tablosu yeterlidir.'),
  ('Geometrik dağılım, sürekli dağılımlardan hangisinin kesikli karşılığı sayılır?', 'Üstel dağılım', ['Normal dağılım', 'Sürekli düzgün dağılım', 'Ki-kare dağılımı'], 'İkisi de bekleme süresini modeller ve belleksizlik özelliğini taşıyan tek kesikli (geometrik) ve tek sürekli (üstel) dağılımlardır.'),
  ('N birimlik bir toplulukta K birim \'başarı\' niteliğindedir. Geri konmadan seçilen n birimdeki başarı sayısının beklenen değeri nedir?', 'nK/N', ['K/N', 'nK/(N − n)', 'n(N − K)/N'], 'Hipergeometrik dağılımın ortalaması, binomdaki gibi n · (K/N)\'dir; geri koymama yalnız varyansı etkiler.'),
  ('Hipergeometrik varyans, binom varyansının (N − n)/(N − 1) ile çarpımına eşittir. Bu çarpana ne ad verilir?', 'Sonlu anakütle düzeltme çarpanı', ['Süreklilik düzeltmesi', 'Yayılım indeksi', 'Bonferroni çoklu karşılaştırma düzeltmesi'], '(N − n)/(N − 1) çarpanı sonlu ve geri koymadan örneklemenin varyansı azaltan etkisini yansıtır.'),
  ('52\'lik desteden geri konmadan 5 kart çekiliyor. Çekilen as sayısının dağılımı hangisidir?', 'Hipergeometrik dağılım', ['Binom(5; 1/13) dağılımı', 'Poisson dağılımı', 'Geometrik dağılım'], 'Sonlu bir desteden geri koymadan çekiş yapıldığı için her çekilişin olasılığı değişir; as sayısı hipergeometrik dağılır.'),
  ('Her denemenin ikiden fazla sonuç kategorisi olduğunda, n bağımsız denemede her kategoriden kaç sonuç geldiğini modelleyen dağılım hangisidir?', 'Multinom dağılımı', ['Binom dağılımı', 'Negatif binom dağılımı', 'Hipergeometrik dağılım'], 'Multinom dağılımı binomun k kategoriye genellemesidir; olasılık n!/(x₁!…x_k!)·p₁^x₁…p_k^x_k biçimindedir.'),
  ('Multinom dağılımlı (X₁, …, X_k) vektöründe tek bir X_i sayımının kendi başına dağılımı nedir?', 'Binom(n, p_i)', ['Poisson(np_i)', 'Multinom(n; p_i)', 'Geometrik(p_i)'], 'Yalnız i. kategoriyi \'başarı\', geri kalanları \'başarısızlık\' sayarsak X_i ~ Binom(n, p_i) olur.'),
  ('Bir yazılımda haftada ortalama 0,5 kritik hata bildirilmektedir ve bildirim sayısı Poisson dağılımına uymaktadır. Bir haftada tam bir hata bildirilme olasılığı yaklaşık kaçtır?', '0,303', ['0,500', '0,607', '0,076'], 'P(X = 1) = e^(−0,5) · 0,5 ≈ 0,6065 · 0,5 ≈ 0,303\'tür.'),
  ('Bir çağrı merkezine dakikada ortalama 2 çağrı gelmektedir (Poisson). Bir dakikada en çok 2 çağrı gelme olasılığı yaklaşık kaçtır?', '0,677', ['0,271', '0,406', '0,594'], 'P(0) + P(1) + P(2) = e^(−2)(1 + 2 + 2) = 5e^(−2) ≈ 0,677\'dir.'),
  ('Bir bölgede yılda ortalama 3 deprem kaydedilmektedir (Poisson). Bir yıl içinde en az bir deprem kaydedilme olasılığı yaklaşık kaçtır?', '0,950', ['0,750', '0,999', '0,850'], 'P(X ≥ 1) = 1 − e^(−3) ≈ 1 − 0,0498 ≈ 0,950\'dir.'),
  ('Bir kumaşta metrekarede ortalama 0,2 dokuma hatası bulunuyor (Poisson). 10 m²\'lik bir parçadaki hata sayısının dağılımı nedir?', 'Poisson(2)', ['Poisson(0,2)', 'Binom(10; 0,2)', 'Poisson(20)'], 'Poisson sürecinde ortalama alanla orantılıdır: 10 · 0,2 = 2. Hata sayısı Poisson(2) dağılır.'),
  ('Poisson dağılımının çarpıklığı 1/√λ\'dır. λ büyüdükçe dağılımın biçimi nasıl değişir?', 'Simetriye yaklaşır', ['Daha çok sağa çarpık olur', 'Sola çarpık hâle gelir', 'Düzgün dağılıma yaklaşır'], '1/√λ, λ büyüdükçe sıfıra yaklaşır; büyük λ için Poisson yaklaşık simetrik, çan biçimli olur.'),
  ('Poisson dağılımında ardışık olasılıklar arasındaki P(X = k)/P(X = k − 1) oranı neye eşittir?', 'λ/k', ['k/λ', 'λ', 'e^(−λ)'], 'e^(−λ)λᵏ/k! ifadesini e^(−λ)λᵏ⁻¹/(k − 1)! ifadesine bölünce λ/k kalır.'),
  ('Bir Poisson değişkeni için P(X = 1) = P(X = 2) olduğu biliniyor. λ kaçtır?', '2', ['1', '0,5', '4'], 'e^(−λ)λ = e^(−λ)λ²/2 eşitliğinden λ = 2 bulunur.'),
  ('Bir Poisson değişkeni için P(X = 0) = 0,2 ise λ yaklaşık kaçtır?', '1,61', ['0,20', '0,80', '5,00'], 'e^(−λ) = 0,2 ise λ = ln 5 ≈ 1,61\'dir.'),
  ('Bir sayım değişkeninin üst sınırı yokken binom yerine Poisson modelinin tercih edilmesinin nedeni nedir?', 'Poisson değerlere bir üst sınır koymaz', ['Poisson\'un varyansı her zaman sıfırdır', 'Poisson yalnızca 0 ve 1 değerini alabilen bir dağılımdır', 'Binom negatif değerler de alır'], 'Binom değişkeni en çok n olabilir; Poisson ise 0, 1, 2, ... biçiminde sınırsız değer alabilir. Deneme sayısı belirsiz sayımlar için bu uygundur.'),
  ('Bir hastanenin acil servisine saatte ortalama 4 hasta yürüyerek, 2 hasta ambulansla gelmektedir; iki akış bağımsız Poisson süreçleridir. Bir saatte gelen toplam hasta sayısının varyansı kaçtır?', '6', ['8', '2', '36'], 'Bağımsız Poisson\'ların toplamı Poisson(4 + 2) = Poisson(6)\'dır; Poisson\'da varyans ortalamaya eşit olduğundan 6\'dır.'),
  ('Binomun Poisson\'a yakınsaması hangi limit durumunda gerçekleşir?', 'n → ∞, p → 0 ve np = λ sabit kalırken', ['n → 0 ve p → 1 iken', 'p sabit kalıp n → ∞ iken', 'n sabit kalıp p → 0,5\'e yaklaşırken ve np değişirken'], 'Poisson limit teoremi, np = λ sabit tutulurken n sonsuza, p sıfıra giderse Binom(n, p) olasılıklarının Poisson(λ) olasılıklarına yakınsadığını söyler.'),
  ('Binom dağılımını Poisson ile yaklaşık hesaplamanın en az uygun olduğu durum hangisidir?', 'n = 20, p = 0,5', ['n = 500, p = 0,004', 'n = 1000, p = 0,001', 'n = 200, p = 0,01'], 'Poisson yaklaşımı p küçükken iyidir. p = 0,5 iken binomun varyansı np(1 − p) = 5, Poisson\'unki 10 olur; fark büyüktür.'),
  ('Varyansın ortalamaya oranı olarak tanımlanan yayılım indeksi Poisson dağılımında kaçtır?', '1', ['0', 'λ', '√λ'], 'Poisson\'da varyans ve ortalama eşit (λ) olduğundan oran 1\'dir. 1\'den büyük değerler aşırı, küçük değerler eksik yayılımı gösterir.'),
  ('Rutherford ve Geiger\'in 1910\'da yayımladıkları deneyde, radyoaktif bir kaynaktan eşit zaman aralıklarında sayılan alfa parçacığı sayılarının hangi dağılıma uyduğu görülmüştür?', 'Poisson dağılımı', ['Binom(2; 0,5) dağılımı', 'Sürekli düzgün dağılım', 'Geometrik dağılım'], 'Radyoaktif bozunmalar bağımsız ve sabit ortalama hızla gerçekleştiği için aralık başına sayımlar Poisson dağılımına çok iyi uyar.'),
  ('Bir zekâ testinin puanları ortalaması 100, standart sapması 15 olan normal dağılıma uyuyor. Standart normal dağılımda z = 0,5 değerinin solunda kalan alan 0,6915 olduğuna göre rastgele bir kişinin 107,5\'ten düşük puan alma olasılığı yaklaşık kaçtır?', '%69,15', ['%30,85', '%50,00', '%19,15'], 'z = (107,5 − 100)/15 = 0,5\'tir; P(X < 107,5) = Φ(0,5) ≈ 0,6915 olur.'),
  ('Bir otobüs hattında yolculuk süresi ortalaması 40 dakika, standart sapması 4 dakika olan normal dağılıma uyuyor. Φ(1,5) ≈ 0,9332 ise yolculuğun 46 dakikadan uzun sürme olasılığı yaklaşık kaçtır?', '0,0668', ['0,9332', '0,15866', '0,04'], 'z = (46 − 40)/4 = 1,5\'tir; P(X > 46) = 1 − Φ(1,5) ≈ 0,0668 bulunur.'),
  ('Standart normal dağılımda Φ(−z) ile Φ(z) arasındaki ilişki hangisidir?', 'Φ(−z) = 1 − Φ(z)', ['Φ(−z) = −Φ(z)', 'Φ(−z) = Φ(z)', 'Φ(−z) = Φ(z) − 0,5'], 'Eğri sıfır etrafında simetrik olduğundan −z\'nin solundaki alan, z\'nin sağındaki alana, yani 1 − Φ(z)\'ye eşittir.'),
  ('Sürekli normal dağılan bir boy değişkeni için P(X = 170 cm) olasılığı kaçtır?', '0', ['Φ(0)', 'Yoğunluk fonksiyonunun 170\'teki değeri', '0,5'], 'Sürekli bir değişkenin tek bir noktayı tam olarak alma olasılığı sıfırdır; olasılıklar yalnızca aralıklar için pozitif olabilir.'),
  ('Normal dağılımda üçüncü çeyrek (Q3) ortalamanın yaklaşık kaç standart sapma üstündedir?', '0,674', ['0,8416', '1', '1,349'], 'Φ(0,674) ≈ 0,75 olduğu için Q3 = μ + 0,674σ\'dır.'),
  ('Normal dağılan bir sınavda ortalama 70\'tir ve öğrencilerin %10\'u 80\'in üstünde puan almıştır. Puanların 60\'ın altında kalma oranı kaçtır?', '%10', ['%20', '%90', '%5'], 'Normal dağılım ortalamaya göre simetrik olduğundan 80 ile 60 ortalamaya eşit uzaklıktadır; alt kuyruk da üst kuyruk kadar, yani %10 olur.'),
  ('Normal dağılan bir değişkenin ortanca %50\'lik kısmı hangi aralıkta yer alır?', 'μ − 0,674σ ile μ + 0,674σ', ['μ − σ ile μ + σ', 'μ − 0,5σ ile μ + 0,5σ', 'μ − 1,1503σ ile μ + 1,1503σ'], 'Orta %50\'lik kısım birinci ve üçüncü çeyrek arasındadır; bunlar μ ∓ 0,674σ\'dır.'),
  ('Başarı olasılığı p olan bağımsız denemelerde ilk başarının kaçıncı denemede geldiğini gösteren geometrik değişken X\'in alabileceği en küçük değer kaçtır?', '1', ['0', 'p', '1/p'], 'İlk deneme başarılı olursa X = 1 olur; deneme sayısı sayıldığı için 0 olamaz. 1/p ise beklenen değerdir.'),
  ('Normal dağılan bir değişkenin karesi ya da logaritması alındığında ortaya çıkan değişken için hangisi genel olarak doğrudur?', 'Artık normal dağılmaz', ['Yine normal dağılır, yalnız ortalaması değişir', 'Standart normal dağılıma dönüşür', 'Düzgün dağılıma dönüşür'], 'Yalnız doğrusal dönüşümler (aX + b) normalliği korur; kare, logaritma gibi doğrusal olmayan dönüşümler dağılımın biçimini değiştirir.'),
  ('Bağımsız iki normal değişkenin toplamının dağılımı hakkında hangisi doğrudur?', 'Yine normaldir; ortalamalar ve varyanslar toplanır', ['Toplam her zaman standart normal dağılıma dönüşür', 'Toplam iki tepeli bir dağılım olur', 'Yalnız ortalamalar eşitse normal olur'], 'Normal dağılım toplama altında kapalıdır: X + Y ~ N(μ₁ + μ₂, σ₁² + σ₂²).'),
  ('Ortalaması μ, standart sapması σ olan normal dağılımın olasılık yoğunluk fonksiyonu hangisidir?', '[1/(σ√(2π))] · e^(−(x − μ)²/(2σ²))', ['[1/(σ√(2π))] · e^(−(x − μ)/(2σ))', '[1/√(2π)] · e^(−(x − μ)²·σ²/2)', '[1/(2πσ²)] · e^((x − μ)²/(2σ²))'], 'Normal yoğunluk, μ etrafında karesel bir üsle azalan ve toplam alanı 1 yapan 1/(σ√(2π)) çarpanını içeren çan eğrisidir.'),
  ('Normal dağılımın yoğunluk eğrisi ortalamadan uzaklaştıkça yatay eksene nasıl yaklaşır?', 'Eksene giderek yaklaşır ama hiç değmez', ['Ortalamadan 3σ uzakta eksene değer', 'Ortalamadan 6σ uzakta sıfır olur', 'Belirli bir noktadan sonra yeniden yükselir'], 'Yoğunluk her x için pozitiftir; kuyruklar yatay ekseni asimptot kabul eder, yani eksene yaklaşır ama dokunmaz.'),
  ('Normal dağılımın çarpıklık katsayısı kaçtır?', '0', ['1', '3', '−1'], 'Normal dağılım ortalamaya göre simetrik olduğundan çarpıklığı sıfırdır.'),
  ('Normal dağılımda ortalamaya göre tek dereceli merkezî momentler (E[(X − μ)³], E[(X − μ)⁵], …) için hangisi doğrudur?', 'Tümü sıfırdır', ['Tümü σ\'ya eşittir', 'Dereceyle birlikte artar', 'Yalnız üçüncüsü sıfırdır, diğerleri pozitiftir'], 'Simetri nedeniyle ortalamanın iki yanındaki katkılar birbirini götürür; tüm tek dereceli merkezî momentler sıfırdır.'),
  ('De Moivre\'nin p = 1/2 için bulduğu binom–normal yaklaşımını herhangi bir p değerine genelleştirdiği için bu sonuç hangi iki matematikçinin adıyla anılır?', 'De Moivre–Laplace teoremi', ['Gauss–Markov teoremi', 'Bernoulli–Euler teoremi', 'Neyman–Pearson lemması ve teoremi'], 'De Moivre–Laplace teoremi, Binom(n, p) dağılımının büyük n için ortalaması np, varyansı np(1 − p) olan normale yaklaştığını söyler.'),
  ('Bir hastanede günlük doğum sayısı Poisson(100) dağılıyor. Normal yaklaşıma göre doğum sayısının standart sapması kaçtır?', '10', ['100', '50', '√50'], 'Poisson\'da varyans λ = 100 olduğundan standart sapma √100 = 10\'dur; büyük λ için N(100; σ = 10) iyi bir yaklaşımdır.'),
  ('Poisson dağılımına normal yaklaşım hangi durumda en iyi sonuç verir?', 'λ büyük olduğunda', ['λ 1\'den küçük olduğunda', 'λ tam sayı olduğunda', 'λ sıfıra yaklaştığında ve olaylar çok seyrekleştiğinde'], 'Poisson\'un çarpıklığı 1/√λ olduğundan λ büyüdükçe dağılım simetrikleşir ve normal yaklaşım iyileşir.'),
  ('Sağa çarpık bir veriyi normal dağılıma yaklaştırmak için logaritma ya da karekök gibi kuvvet dönüşümleri arasından en uygun olanı veriden seçen yöntem hangisidir?', 'Box-Cox dönüşümü', ['Fourier dönüşümü', 'z dönüşümü', 'Laplace dönüşümü ve ters dönüşümü'], 'Box-Cox dönüşümü (xᵝ − 1)/λ ailesinden veriyi en çok normale yaklaştıran λ değerini seçer; λ = 0 logaritmaya karşılık gelir.'),
  ('Bağımsız k tane standart normal değişkenin karelerinin toplamı hangi dağılıma uyar?', 'Serbestlik derecesi k olan ki-kare dağılımı', ['Ortalaması k olan normal dağılım', 'Serbestlik derecesi k − 1 olan Student t dağılımı', 'Oranı k olan üstel dağılım'], 'Z₁² + … + Z_k² ~ χ²(k)\'dir; bu dağılımın ortalaması k, varyansı 2k\'dir.'),
  ('Student t dağılımı ile standart normal dağılım karşılaştırıldığında hangisi doğrudur?', 't\'nin kuyrukları daha kalındır; serbestlik derecesi arttıkça normale yaklaşır', ['t her zaman normalden daha dar ve sivridir', 't sağa çarpıktır, normal ise simetriktir', 't yalnız pozitif değerler alır ve serbestlik derecesi büyüdükçe sağa kayar'], 't dağılımı da sıfır etrafında simetrik ve çan biçimlidir; ancak kuyrukları daha kalındır ve serbestlik derecesi büyüdükçe standart normale yakınsar.'),
  ('Bir Poisson sürecinde k. olaya kadar geçen süre, k tane bağımsız üstel bekleme süresinin toplamıdır. Bu toplamın dağılımına ne ad verilir?', 'Erlang (gamma) dağılımı', ['Normal dağılım', 'Geometrik dağılım', 'Weibull\'un özel bir türü olan Rayleigh dağılımı'], 'Oranı λ olan k tane bağımsız üstel değişkenin toplamı, biçim parametresi k olan gamma dağılımına, yani Erlang dağılımına uyar.'),
  ('Poisson sürecinde ilk olayın t anından sonra gerçekleşmesi olayı, aşağıdakilerden hangisiyle aynı olaydır?', '[0, t] aralığında hiç olay olmaması', ['[0, t] aralığında tam bir olay olması', '[0, t] aralığında en az bir olay olması', 't anında bir olay olması'], 'İlk olay t\'den sonraysa [0, t] aralığında olay sayısı sıfırdır; bu yüzden P(T₁ > t) = P(N(t) = 0) = e^(−λt)\'dir.'),
  ('Üstel dağılımda standart sapma ile ortalama arasındaki ilişki nedir?', 'Birbirine eşittir', ['Standart sapma ortalamanın karesidir', 'Standart sapma ortalamanın yarısıdır', 'Standart sapma her zaman 1\'dir'], 'Oranı λ olan üstel dağılımda ortalama 1/λ, varyans 1/λ²\'dir; dolayısıyla standart sapma da 1/λ\'dır.'),
  ('Poisson sürecinin \'bağımsız artışlar\' özelliği neyi ifade eder?', 'Örtüşmeyen zaman aralıklarındaki olay sayıları birbirinden bağımsızdır', ['Olay sayısı zamanla sürekli artar', 'Her aralıkta aynı sayıda olay gerçekleşir', 'Bir aralıktaki olay sayısı bir önceki aralıktaki sayının iki katı olur'], 'Bağımsız artışlar, örneğin 9:00–10:00 ile 10:00–11:00 aralıklarındaki olay sayılarının birbirini etkilemediğini söyler.'),
  ('Bir Poisson sürecinde ardışık iki olay arasındaki süreler hangi dağılıma uyar?', 'Bağımsız ve aynı üstel dağılıma', ['Bağımsız Poisson dağılımlarına', 'Ortalaması λ olan normal dağılıma', 'Sabit, değişmeyen bir değere'], 'Poisson sürecinin denk bir tanımı, olaylar arası sürelerin bağımsız ve oranı λ olan üstel dağılıma uymasıdır.'),
  ('Kusur oranı %3 olan çok büyük bir üretimden rastgele seçilen 20 üründeki kusurlu ürün sayısı için en uygun model hangisidir?', 'Binom(20; 0,03)', ['Poisson(0,03)', 'Normal(20; 0,03)', 'Geometrik(0,03)'], 'Sabit sayıda (20) bağımsız ürün ve her birinde aynı kusur olasılığı (0,03) vardır; üretim çok büyük olduğundan geri koymama etkisi ihmal edilir.'),
  ('Bir kişinin iki zarı birlikte atarak ilk kez çift altı getirene kadar yaptığı atış sayısı hangi dağılıma uyar?', 'p = 1/36 olan geometrik dağılım', ['n = 36 olan binom dağılımı', 'λ = 1/36 olan Poisson dağılımı', 'Ortalaması 36 olan normal dağılım'], 'Her atış bağımsız ve çift altı olasılığı 1/36\'dır; ilk başarıya kadarki deneme sayısı geometrik dağılır.'),
  ('Hassas bir laboratuvar terazisiyle aynı cismin yüzlerce kez tartılmasında oluşan ölçüm hataları için en uygun model hangisidir?', 'Ortalaması 0 olan normal dağılım', ['Ortalaması 0 olan Poisson dağılımı', 'Üstel dağılım', 'Geometrik dağılım'], 'Ölçüm hataları birçok küçük ve bağımsız etkinin toplamıdır; pozitif ve negatif olabilir, sıfır etrafında simetrik toplanır. Bu, normal dağılımın klasik uygulamasıdır.'),
  ('Bir bilgisayar programındaki rastgele sayı üreticisi 0 ile 1 arasında herhangi bir gerçek sayıyı eşit olasılıkla veriyor. Bu sayının dağılımı nedir?', '[0, 1] aralığında sürekli düzgün dağılım', ['Ortalaması 0,5 olan normal dağılım', 'p = 0,5 olan Bernoulli dağılımı', '0, 1, 2, …, 9 değerleri üzerinde kesikli düzgün dağılım'], 'Aralıktaki her eşit uzunluklu alt aralığın olasılığı aynıdır; değerler sürekli olduğundan dağılım sürekli düzgün dağılımdır.'),
  ('Bir otoyolun her kilometresindeki çukur sayısı inceleniyor; çukurların yol boyunca rastgele ve birbirinden bağımsız oluştuğu düşünülüyor. Bu sayım için en uygun dağılım hangisidir?', 'Poisson dağılımı', ['Binom(1; p) dağılımı', 'Hipergeometrik dağılım', 'Negatif binom dağılımı, çünkü çukur sayısı sınırsızdır'], 'Bir uzunluk biriminde rastgele ve bağımsız oluşan olayların sayısı Poisson sürecinin uzamsal karşılığıdır.'),
  ('Bir sınıftaki 12 kız ve 18 erkek öğrenciden kurayla 5 kişilik bir komisyon seçiliyor. Komisyondaki kız sayısının dağılımı hangisidir?', 'Hipergeometrik dağılım', ['Binom(5; 0,4) dağılımı', 'Poisson(2) dağılımı', 'Negatif binom dağılımı'], 'Sonlu bir gruptan geri koymadan seçim yapıldığı için her seçimde kız seçilme olasılığı değişir; kız sayısı hipergeometrik dağılır.'),
  ('Ömür sürelerinin modellenmesinde kullanılan Weibull dağılımında biçim parametresi k = 1 alınırsa hangi dağılım elde edilir?', 'Üstel dağılım', ['Normal dağılım', 'Poisson dağılımı', 'Sürekli düzgün dağılım'], 'Weibull, üstel dağılımın genellemesidir: k = 1\'de tehlike oranı sabittir (üstel); k > 1\'de yıpranmayla artan, k < 1\'de azalan tehlike oranı elde edilir.'),
  ('Geometrik dağılımın bu adı almasının nedeni nedir?', 'Ardışık olasılıkların ortak oranı 1 − p olan bir geometrik dizi oluşturması', ['Geometri problemlerinde kullanılması', 'Olasılıkların bir daire üzerinde gösterilmesi', 'Ortalamasının geometrik ortalama olması'], 'P(X = 1) = p, P(X = 2) = p(1 − p), P(X = 3) = p(1 − p)², … dizisinin her terimi bir öncekinin (1 − p) katıdır.'),
  ('Negatif binom dağılımının, r. başarıya kadar geçen deneme sayısı biçimindeki tanımı için literatürde kullanılan diğer ad hangisidir?', 'Pascal dağılımı', ['Fermat dağılımı', 'Bernoulli dağılımı', 'Laplace dağılımı'], 'r tam sayı olduğunda negatif binom dağılımı Pascal dağılımı olarak da anılır; ad, binom katsayılarıyla ilişkili olduğu için Blaise Pascal\'dan gelir.'),
  ('Bir birikimli dağılım fonksiyonu F(x) için x → −∞ ve x → +∞ iken limit değerleri sırasıyla nedir?', '0 ve 1', ['−1 ve 1', '0 ve ∞', '1 ve 0'], 'F(x) = P(X ≤ x) olduğundan çok küçük x için olasılık 0\'a, çok büyük x için 1\'e yaklaşır.'),
  ('Sürekli ve kesikli değişkenler arasında P(X ≤ 5) ile P(X < 5) karşılaştırıldığında hangisi doğrudur?', 'Sürekli değişkende eşittirler; kesikli değişkende farklı olabilirler', ['Her iki türde de her zaman eşittirler', 'Her iki türde de her zaman farklıdırlar', 'Kesikli değişkende her zaman eşit, sürekli değişkende ise her zaman farklıdırlar'], 'Sürekli değişkende P(X = 5) = 0 olduğundan iki olasılık eşittir; kesikli değişkende aradaki fark P(X = 5) kadardır.'),
  ('Bir ürünün ömrü için S(t) = 1 − F(t) biçiminde tanımlanan fonksiyona ne ad verilir?', 'Hayatta kalma (dayanıklılık) fonksiyonu', ['Olasılık kütle fonksiyonu', 'Moment üreten fonksiyon', 'Olabilirlik (likelihood) fonksiyonu ve logaritması'], 'S(t) = P(T > t), ürünün t anından sonra hâlâ çalışıyor olma olasılığıdır; güvenilirlik ve sağkalım analizinde temel araçtır.'),
  ('Bir bilgisayar benzetiminde düzgün dağılmış U sayısını birikimli dağılım fonksiyonunun tersine (F⁻¹(U)) koyarak istenen dağılımdan sayı üreten yönteme ne ad verilir?', 'Ters dönüşüm yöntemi', ['Kabul-ret yöntemi', 'Bootstrap yöntemi', 'En küçük kareler yöntemi'], 'Ters dönüşüm yönteminde P(F⁻¹(U) ≤ x) = P(U ≤ F(x)) = F(x) olduğundan üretilen sayılar F dağılımına uyar.'),
  ('Bir X değişkeninin moment üreten fonksiyonu nasıl tanımlanır?', 'M(t) = E(e^(tX))', ['M(t) = E(X^t)', 'M(t) = e^(t·E(X))', 'M(t) = P(X ≤ t)'], 'Moment üreten fonksiyon E(e^(tX))\'tir; t = 0\'daki türevleri sırasıyla E(X), E(X²), … momentlerini verir.'),
  ('Moment üreten fonksiyon M(t)\'nin t = 0 noktasındaki birinci türevi neyi verir?', 'Beklenen değeri', ['Varyansı', 'Medyanı', 'P(X = 0) olasılığını'], 'M′(t) = E(X·e^(tX)) olduğundan M′(0) = E(X)\'tir. İkinci türev M″(0) ise E(X²)\'yi verir.'),
  ('Kabul örneklemesinde, partinin gerçek kusur oranına karşı partinin kabul edilme olasılığını gösteren eğriye ne ad verilir?', 'İşletim karakteristiği (OC) eğrisi', ['ROC eğrisi', 'Lorenz eğrisi', 'Öğrenme eğrisi ya da deneyim eğrisi'], 'OC eğrisi, bir örnekleme planının farklı kusur oranlarında partileri ne olasılıkla kabul ettiğini gösterir; planların ayırt etme gücünü karşılaştırmaya yarar.'),
  ('Kabul örneklemesinde \'üretici riski\' neyi ifade eder?', 'Kalitesi iyi bir partinin yanlışlıkla reddedilme olasılığını', ['Kalitesi kötü bir partinin yanlışlıkla kabul edilip tüketiciye ulaşma olasılığını', 'Üreticinin kusurlu ürün üretme oranını', 'Partinin hiç incelenmeme olasılığını'], 'Üretici riski (α) kabul edilebilir kalitedeki bir partinin reddedilmesi, tüketici riski (β) ise kötü bir partinin kabul edilmesi olasılığıdır.'),
  ('Anne ve babası Aa genotipli 4 çocuklu bir ailede her çocuğun aa olma olasılığı bağımsız olarak 1/4\'tür. Çocuklardan tam birinin aa olma olasılığı yaklaşık kaçtır?', '0,42', ['0,25', '0,32', '0,105'], 'C(4,1) · (1/4) · (3/4)³ = 4 · 27/256 = 108/256 ≈ 0,42\'dir.'),
  ('Bir jüride her üye bağımsız olarak 0,5\'ten büyük bir olasılıkla doğru karar veriyorsa, üye sayısı arttıkça çoğunluk kararının doğru olma olasılığının 1\'e yaklaştığını söyleyen teorem kimin adıyla anılır?', 'Condorcet', ['Bayes', 'Pascal', 'Fermat'], 'Condorcet jüri teoremi (1785), çoğunluğun doğru olma olasılığının binom dağılımına dayanarak üye sayısıyla arttığını gösterir.'),
  ('Normal dağılan bir değişkenin ortalamaya göre simetrik ve değerlerin %95\'ini içeren aralığı hangisidir?', 'μ − 1,96σ ile μ + 1,96σ', ['μ − 1,645σ ile μ + 1,645σ', 'μ − 2,576σ ile μ + 2,576σ', 'μ − 3σ ile μ + 3σ'], 'Her kuyrukta %2,5 kalması için z = 1,96 kullanılır; 1,645 ise %90\'lık aralığı verir.'),
  ('İki normal dağılım farklı ortalama ve standart sapmalara sahiptir. Her birinde \'ortalamanın 1,5 standart sapma üstünü aşma\' olasılığı karşılaştırılırsa hangisi doğrudur?', 'İki olasılık eşittir', ['Standart sapması büyük olanda olasılık büyüktür', 'Ortalaması büyük olanda olasılık büyüktür', 'Karşılaştırma için ham değerler gerekir'], 'P(X > μ + 1,5σ) = P(Z > 1,5) olup μ ve σ\'dan bağımsızdır; standartlaştırma bütün normal dağılımları aynı ölçeğe getirir.'),
  ('Bir müzeye dakikada ortalama 2,5 ziyaretçi giriyor (Poisson). Belirli bir dakikada tam 2 ziyaretçi girme olasılığı yaklaşık kaçtır?', '0,257', ['0,082', '0,205', '0,4000'], 'P(X = 2) = e^(−2,5) · 2,5²/2 ≈ 0,0821 · 3,125 ≈ 0,257\'dir.'),
  ('Bir köprüde yılda ortalama 1,5 kez bakım gerektiren arıza oluyor (Poisson). Bir yılda en çok bir arıza olma olasılığı yaklaşık kaçtır?', '0,558', ['0,223', '0,335', '0,7769'], 'P(0) + P(1) = e^(−1,5)(1 + 1,5) ≈ 0,2231 · 2,5 ≈ 0,558\'dir.'),
  ('Poisson dağılımına uyan bir değişken için P(X = 0) = P(X = 1) ise λ kaçtır?', '1', ['0', '0,5', 'e'], 'e^(−λ) = λe^(−λ) eşitliğinden λ = 1 bulunur.'),
  ('Bir maçta ev sahibinin gol sayısı Poisson(1,5), konuk takımınki Poisson(1,0) ve ikisi bağımsız kabul ediliyor. Maçın 0–0 bitme olasılığı yaklaşık kaçtır?', '0,082', ['0,223', '0,368', '0,0500'], 'P(0–0) = e^(−1,5) · e^(−1,0) = e^(−2,5) ≈ 0,082\'dir.'),
  ('Normal dağıldığı bilinen bir değişkenin medyanı 72 olarak bulunmuştur. Ortalaması kaçtır?', '72', ['36', 'Bilinmeden hesaplanamaz', 'Yaklaşık 75'], 'Normal dağılım simetrik olduğundan ortalama, medyan ve mod aynı noktadadır; ortalama da 72\'dir.'),
  ('Standart sapması 5 olan normal dağılımlı bir değişkenin değerlerinin %2,28\'i 30\'un altındadır. Φ(2) ≈ 0,9772 olduğuna göre ortalama kaçtır?', '40', ['35', '30', '42,28'], '30\'un z değeri −2 olmalıdır: μ = 30 + 2 · 5 = 40.'),
  ('Normal dağılan bir değişkende ortalamaya göre simetrik ve değerlerin %99\'unu içeren aralık için kaç standart sapma kullanılır?', '2,576', ['2,326', '1,960', '3,000'], 'Her kuyrukta %0,5 kalması gerekir; Φ(2,576) ≈ 0,995\'tir. 2,326 ise tek kuyruklu %1\'lik eşiktir.'),
  ('Ortalaması 120 olan normal dağılımlı bir değişkenin 97,5. yüzdeliği 159,2\'dir. Standart sapma kaçtır?', '20', ['39,2', '19,6', '10'], '97,5. yüzdelik μ + 1,96σ\'dır: σ = (159,2 − 120)/1,96 = 20.'),
  ('Binom dağılımına normal yaklaşımın aynı n için en iyi sonuç verdiği p değeri hangisidir?', '0,5', ['0,01', '0,99', '0,1'], 'p = 0,5\'te binom simetriktir; p uçlara yaklaştıkça çarpıklık artar ve normal yaklaşım için daha büyük n gerekir.'),
  ('İkinci başarıya kadar geçen deneme sayısı p = 0,5 olan negatif binom dağılımına uyuyor. Bu deneme sayısının varyansı r(1 − p)/p² formülüne göre kaçtır?', '4', ['2', '1', '8'], 'r = 2, p = 0,5 için varyans 2 · 0,5/0,25 = 4\'tür.'),
  ('52 kartlık iyi karıştırılmış bir desteden dağıtılan 13 kartlık bir elde bulunan as sayısının beklenen değeri kaçtır?', '1', ['4', '0,25', '13/4'], 'Hipergeometrik ortalama nK/N = 13 · 4/52 = 1\'dir.'),
  ('Bir öğrenci \'Poisson dağılımının λ parametresi bir sayım ortalaması olduğu için tam sayı olmak zorundadır\' diyor. Bu ifade hakkında ne söylenebilir?', 'Yanlıştır; λ herhangi bir pozitif gerçek sayı olabilir', ['Doğrudur; λ yalnız 1, 2, 3, … gibi pozitif tam sayılardan biri olabilir', 'Doğrudur; λ en çok 10 olabilir', 'Yanlıştır; λ negatif de olabilir'], 'Değişkenin aldığı değerler tam sayıdır ama ortalaması 0,61 ya da 2,5 gibi kesirli olabilir; λ > 0 olan her gerçek sayı geçerlidir.'),
  ('Geri koymadan yapılan bir seçimde, örneklem anakütlenin yaklaşık %10\'unu aşmıyorsa binom modeli neden yine de kullanılabilir?', 'Seçimler neredeyse bağımsız olduğundan olasılık pek değişmez', ['Geri koymadan seçimde denemeler her koşulda tam olarak bağımsızdır', 'Binom yalnız sonlu anakütlelerde geçerlidir', '%10\'dan küçük örneklemlerde varyans sıfırdır'], 'Anakütle örnekleme göre büyükse her seçimden sonra başarı oranı çok az değişir; hipergeometrik dağılım binoma çok yakın olur.'),
  ('λ parametresi sıfıra yaklaştırılan bir Poisson dağılımında P(X = 0) hangi değere yaklaşır?', '1', ['0', '0,5', 'e^(−1)'], 'P(X = 0) = e^(−λ) olup λ → 0 iken e⁰ = 1\'e gider; olay neredeyse hiç gerçekleşmez.'),
  ('Üç çocuklu 80 ailenin olduğu bir mahallede her doğumun bağımsız olarak 1/2 olasılıkla kız olduğu varsayılıyor. Üç çocuğunun da kız olduğu aile sayısının beklenen değeri kaçtır?', '10', ['20', '30', '26,7'], 'Bir ailenin üç kız çocuğu olma olasılığı (1/2)³ = 1/8\'dir; 80 · 1/8 = 10 aile beklenir.'),
  ('Binom dağılımının büyük n için normale yaklaşmasının merkezî limit teoremiyle açıklaması hangisidir?', 'Binom değişkeni bağımsız Bernoulli değişkenlerinin toplamıdır', ['Binom dağılımı her n ve her p değeri için tam simetriktir', 'Binom dağılımının varyansı n büyüdükçe sıfırlanır ve değerler sabitleşir', 'Binom değişkeni sürekli değerler alır'], 'X = X₁ + … + Xₙ biçiminde bağımsız ve özdeş Bernoulli değişkenlerinin toplamı olduğundan, merkezî limit teoremi standartlaştırılmış X\'in normale yaklaştığını söyler.'),
  ('Göstergesel değişkenlerin toplamının beklenen değeri hesaplanırken değişkenlerin birbirine bağımlı olması neyi değiştirir?', 'Beklenen değeri değiştirmez; yalnız varyans hesabını etkiler', ['Beklenen değer artık toplanamaz, kovaryanslar da eklenmelidir', 'Beklenen değer her zaman sıfır olur', 'Hem beklenen değer hem varyans aynı kalır'], 'Beklenen değerin doğrusallığı bağımlılıktan bağımsız olarak geçerlidir: E(ΣIᵢ) = ΣP(Aᵢ). Varyans ise kovaryans terimleri gerektirir.'),
  ('Bağımsız ve aynı normal dağılıma sahip iki değişkenden birincisinin ikincisinden büyük olma olasılığı kaçtır?', '1/2', ['1/4', 'Ortalamaya bağlıdır', 'Standart sapmaya bağlıdır'], 'X − Y farkı ortalaması 0 olan simetrik bir normal dağılıma uyar; bu yüzden P(X > Y) = 1/2\'dir.'),
  ('Normal yaklaşımın bir binom ya da Poisson olasılığını hesaplarken en büyük göreli hatayı genellikle hangi bölgede yaptığı söylenebilir?', 'Dağılımın uç kuyruklarında', ['Tam ortalamanın üzerinde', 'Ortalamanın bir standart sapma çevresinde', 'Medyan ile mod arasında'], 'Merkez bölgede yaklaşım iyidir; ama çok küçük kuyruk olasılıklarında çarpıklık nedeniyle göreli hata büyür.'),
  ('Psikometride kullanılan dokuz basamaklı \'stanine\' puanlarında dağılım normal varsayılır. Bu ölçeğin ortalaması ve standart sapması nedir?', 'Ortalama 5, standart sapma 2', ['Ortalama 50, standart sapma 10', 'Ortalama 100, standart sapma 15', 'Ortalama 0, standart sapma 1'], 'Stanine (\'standard nine\') ölçeği 1\'den 9\'a kadar puanlar verir; ortalaması 5, standart sapması yaklaşık 2\'dir. 50–10 T-puanı, 100–15 zekâ ölçeklerine aittir.'),
  ('Normal dağılan bir değişkenin ortalamaya uzaklığının k standart sapmadan az olma olasılığı P(|X − μ| < kσ), Φ ile hangi biçimde yazılır?', '2Φ(k) − 1', ['Φ(k) − 1', '1 − 2Φ(k)', '2Φ(k)'], 'P(−k < Z < k) = Φ(k) − Φ(−k) = Φ(k) − [1 − Φ(k)] = 2Φ(k) − 1\'dir.'),
  ('Yetişkin boylarının yaklaşık normal dağılmasının en yaygın açıklaması hangisidir?', 'Boy, çok sayıda gen ve çevre etkisinin küçük katkılarının toplamıdır', ['Boyu tek bir gen belirler', 'İnsanlar beslenmeleriyle boylarını bilinçli olarak ortalamaya yaklaştırır', 'Boy ölçümleri her zaman yuvarlanır'], 'Birçok küçük ve kabaca bağımsız etkinin toplamı, merkezî limit teoremi uyarınca yaklaşık normal dağılır; bu yüzden boy gibi poligenik özellikler çan eğrisine benzer.'),
  ('X ~ Binom(n, p) değişkeni normal yaklaşım için hangi ifadeyle standartlaştırılır?', '(X − np)/√(np(1 − p))', ['(X − p)/√(np)', '(X − np)/(np(1 − p))', '(X − n·p)/√(n·p) −'], 'Ortalama np çıkarılıp standart sapma √(np(1 − p))\'ye bölünür; büyük n için bu oran yaklaşık standart normal dağılır.'),
  ('Parçacık fiziğinde bir keşif ilan etmek için kullanılan \'5 sigma\' ölçütü, tek kuyruklu standart normal olasılık olarak yaklaşık hangi değere karşılık gelir?', 'Yaklaşık 3,5 milyonda 1', ['Yaklaşık 20\'de 1', 'Yaklaşık 370\'te 1', 'Yaklaşık 1000\'de 1'], 'P(Z > 5) ≈ 2,9 × 10⁻⁷\'dir; bu yaklaşık 3,5 milyonda 1 demektir. 2012\'de Higgs bozonunun keşfi bu ölçütle duyurulmuştur.'),
  ('Bağımsız iki ki-kare değişkeninin her biri kendi serbestlik derecesine bölünüp oranı alındığında hangi dağılım elde edilir?', 'F dağılımı', ['t dağılımı', 'Normal dağılım', 'Poisson dağılımı'], '(χ²₁/d₁)/(χ²₂/d₂) oranı d₁ ve d₂ serbestlik dereceli F dağılımına uyar; varyans oranlarının karşılaştırılmasında kullanılır.'),
  ('Jakob Bernoulli\'nin ölümünden sonra 1713\'te yayımlanan ve Bernoulli denemeleri ile binom dağılımını sistematik biçimde işleyen eserinin adı nedir?', 'Ars Conjectandi', ['The Doctrine of Chances', 'Liber de Ludo Aleae', 'Théorie analytique des probabilités'], '\'Tahmin Sanatı\' anlamına gelen Ars Conjectandi, permütasyon-kombinasyon kuramını, binom olasılıklarını ve büyük sayılar yasasının ilk kanıtını içerir.'),
  ('İki değişken ortak normal dağılıyorsa, eşit olasılık yoğunluğuna sahip noktaları birleştiren eğriler (eş yoğunluk eğrileri) hangi biçimdedir?', 'Elips', ['Doğru', 'Parabol', 'Kare'], 'Ortak normal yoğunluğun üssü ikinci dereceden bir ifadedir; sabit tutulduğunda elips verir. Korelasyon sıfır ve varyanslar eşitse elipsler çembere dönüşür.'),
  ('Birbirinden bağımsız ve aynı başarı olasılığına sahip Bernoulli denemelerinin sonsuz dizisine ne ad verilir?', 'Bernoulli süreci', ['Poisson süreci', 'Markov zinciri', 'Wiener süreci'], 'Bernoulli süreci kesikli zamanlı bir süreçtir; binom (sabit n\'deki başarı sayısı), geometrik ve negatif binom dağılımları bu süreçten türetilir. Poisson süreci onun sürekli zamandaki karşılığıdır.'),
  ('Biçim parametresi k ve ölçek parametresi θ olan gamma dağılımının ortalaması ve varyansı nedir?', 'kθ ve kθ²', ['θ/k ve θ²/k', 'kθ ve k²θ', 'k/θ ve k/θ²'], 'Gamma(k, θ), ortalaması θ olan k tane bağımsız üstelin toplamı gibi düşünülebilir (k tam sayıyken): ortalamalar toplanarak kθ, varyanslar toplanarak kθ² bulunur.'),
  ('Poisson olasılıklarının toplamının 1 olduğu, hangi seri açılımı kullanılarak gösterilir?', 'e^λ = Σ λᵏ/k!', ['(1 + λ)ⁿ binom açılımı', 'Geometrik seri: Σ λᵏ = 1/(1 − λ), |λ| < 1', 'Harmonik seri Σ 1/k'], 'Σ e^(−λ)λᵏ/k! = e^(−λ) · e^λ = 1 olur; üstel fonksiyonun Taylor serisi Poisson\'un temelidir.'),
  ('Bir fırıncı, çöreklerdeki kuru üzüm sayısının Poisson dağıldığını biliyor ve hiç üzüm içermeyen çörek oranının %1\'i aşmamasını istiyor. Çörek başına ortalama en az kaç üzüm konmalıdır?', 'Yaklaşık 4,6', ['1', 'Yaklaşık 2,3', '100'], 'e^(−λ) ≤ 0,01 için λ ≥ ln 100 ≈ 4,6 olmalıdır.'),
  ('Standart normal birikimli dağılım Φ(z) değerlerinin hesap makinesi yerine tablo ya da sayısal yöntemlerle bulunmasının nedeni nedir?', 'e^(−x²/2) fonksiyonunun integrali temel fonksiyonlarla kapalı biçimde yazılamaz', ['Φ(z) yalnız tam sayı z\'ler için tanımlıdır', 'Normal dağılımın eğri altındaki toplam alanı tam olarak bilinmemektedir', 'Φ(z) negatif değerler alabilir'], 'Gauss eğrisinin belirsiz integrali bilinen temel fonksiyonlarla ifade edilemez; Φ bu yüzden seri açılımları, tablolar ya da erf gibi özel fonksiyonlarla hesaplanır.'),
  ('Bir cihazın ömrü ortalaması 10 yıl olan üstel dağılıma uyuyor. Cihazın 5. yıl ile 10. yıl arasında bozulma olasılığı yaklaşık kaçtır?', '0,24', ['0,50', '0,37', '0,6065'], 'P(5 < T < 10) = e^(−0,5) − e^(−1) ≈ 0,607 − 0,368 ≈ 0,24\'tür.'),
  ('Aşağıdaki dağılımlardan hangisinin alabileceği değerler kümesi sonludur?', 'Hipergeometrik dağılım', ['Poisson dağılımı', 'Geometrik dağılım', 'Negatif binom dağılımı'], 'Hipergeometrik değişken en çok min(n, K) değerini alabilir; Poisson, geometrik ve negatif binom ise sınırsız sayıda değer alabilir.'),
  ('Aşağıdaki dağılımlardan hangisi parametreleri ne olursa olsun her zaman simetriktir?', 'Normal dağılım', ['Binom dağılımı', 'Poisson dağılımı', 'Üstel dağılım'], 'Normal dağılım her μ ve σ için ortalamaya göre simetriktir. Binom yalnız p = 0,5 iken simetriktir; Poisson ve üstel her zaman sağa çarpıktır.'),
  ('Dağılımlar ile alabildikleri değer kümeleri eşleştirilmiştir. Hangi eşleştirme yanlıştır?', 'Üstel dağılım: tüm gerçek sayılar', ['Poisson: 0, 1, 2, …', 'Binom(n, p): 0, 1, …, n arasındaki tam sayılar', 'Normal: tüm gerçek sayılar'], 'Üstel dağılım yalnız negatif olmayan gerçek değerler alır; bekleme süresi negatif olamaz.'),
  ('Aşağıdaki dağılımlardan hangisi tek bir parametreyle tamamen belirlenir?', 'Poisson dağılımı', ['Normal dağılım', 'Binom dağılımı', 'Hipergeometrik dağılım'], 'Poisson yalnız λ ile belirlenir; normal (μ, σ), binom (n, p) ve hipergeometrik (N, K, n) birden fazla parametre gerektirir.'),
  ('Başarı olasılığı p > 0 olan bir olay için bağımsız deneme sayısı n sınırsız artırılırsa en az bir başarı olasılığı 1 − (1 − p)ⁿ hangi değere yaklaşır?', '1', ['p', '1 − p', '0,5'], '(1 − p)ⁿ, n büyüdükçe sıfıra gider; ne kadar küçük olursa olsun pozitif olasılıklı bir olay yeterince çok denemede neredeyse kesin gerçekleşir.'),
  ('Bir maç ölçüm sisteminde bir oyuncunun \'şut isabet sayısı\' 10 şutta Binom(10; p), bir maçta attığı gol sayısı ise Poisson(λ) olarak modelleniyor. Bu iki modelin temel farkı nedir?', 'Binomda deneme sayısı sabit ve üst sınır vardır; Poisson\'da yoktur', ['Binom sürekli, Poisson kesiklidir', 'Binomun varyansı her zaman ortalamasından büyüktür, Poisson\'unki küçüktür', 'Poisson yalnız 0 ve 1 değerini alır'], 'Binomda n deneme sayılır ve X ≤ n\'dir; Poisson ise sabit bir zaman aralığındaki olay sayısını, belirli bir üst sınır olmaksızın modeller.'),
  ('İstatistik kitaplarında standart normal dağılım için kullanılan φ(z) ve Φ(z) gösterimleri neyi ifade eder?', 'φ yoğunluk fonksiyonunu, Φ birikimli dağılım fonksiyonunu', ['φ birikimli dağılımı, Φ ise yoğunluk fonksiyonunun türevini', 'İkisi de yoğunluk fonksiyonudur', 'φ ortalamayı, Φ standart sapmayı'], 'Küçük harf φ(z) = e^(−z²/2)/√(2π) yoğunluğu; büyük harf Φ(z) = P(Z ≤ z) ise birikimli olasılığı gösterir.'),
  ('Yaygın standart normal tabloları genellikle hangi alanı verir?', 'z\'nin solundaki alanı, yani P(Z ≤ z)', ['z\'nin sağındaki alanı her zaman', 'Yalnız 0 ile z arasındaki alanı her zaman', 'Yoğunluk eğrisinin z\'deki yüksekliğini'], 'Çoğu tablo birikimli olasılık Φ(z)\'yi verir; bazı tablolar 0 ile z arasını verdiğinden tablonun başlığına bakmak gerekir. Sağ kuyruk 1 − Φ(z) ile bulunur.'),
  ('Bir Poisson sürecinde örneğin 9.00–9.10 ile 15.00–15.10 aralıklarındaki olay sayılarının aynı dağılıma uyması hangi özellikle açıklanır?', 'Durağan artışlar: dağılım yalnız aralığın uzunluğuna bağlıdır', ['Bağımsız artışlar: aralıklar birbirini etkilemez', 'Belleksizlik: geçmiş bekleme süresi önemsizdir', 'Düzenlilik: olaylar eşit aralıklarla gelir'], 'Durağanlık, bir aralıktaki olay sayısının dağılımının aralığın nerede olduğuna değil yalnız uzunluğuna bağlı olmasıdır; iki 10 dakikalık aralık da Poisson(10λ) dağılır.'),
  ('Binom olasılık formülündeki C(n, k) çarpanı neyi sayar?', 'n denemede k başarının yer alabileceği farklı sıralamaların sayısını', ['k başarının olasılığını', 'Başarısızlık sayısını', 'Denemelerin birbirinden ne ölçüde bağımsız olduğunu gösteren katsayıyı'], 'Belirli bir sıralamanın olasılığı pᵏ(1 − p)ⁿ⁻ᵏ\'dır; k başarının n denemeye yerleşebileceği C(n, k) sıralamanın hepsi aynı olasılıklı olduğundan bu çarpanla çarpılır.'),
  ('Poisson(λ) dağılımı için P(X = k) değerleri k\'ya karşı çizildiğinde λ = 0,5 ve λ = 8 için grafiklerin biçimi nasıldır?', 'λ = 0,5\'te sıfırdan itibaren azalan, λ = 8\'de yaklaşık çan biçimli', ['İkisi de düz bir çizgidir', 'λ = 0,5\'te çan biçimli, λ = 8\'de sıfırdan itibaren azalan', 'İkisi de sola çarpıktır'], 'λ < 1 iken mod 0\'dır ve olasılıklar sürekli azalır; büyük λ\'da dağılım λ çevresinde toplanıp yaklaşık simetrik olur.'),
  ('Bir parçanın çapı normal dağılıyor; ölçülerin %99,73\'ünün hedef ±0,3 mm aralığında kalması isteniyor. Sürecin standart sapması en çok kaç mm olmalıdır?', '0,10', ['0,30', '0,15', '0,05'], '%99,73 aralığı ±3σ\'dır; 3σ = 0,3 mm\'den σ = 0,1 mm bulunur.'),
  ('X ~ Poisson(3) için E(X²) kaçtır?', '12', ['9', '3', '6'], 'E(X²) = Var(X) + [E(X)]² = 3 + 9 = 12\'dir.'),
  ('On denemelik ve başarı olasılığı 0,3 olan bir binom deneyinde başarı sayısının ortancası (medyanı) için genel kural nedir?', 'np\'nin aşağı ya da yukarı yuvarlanmışı olan tam sayılardan biridir', ['Her zaman n/2\'dir', 'Her zaman 0\'dır', 'Her zaman p\'ye eşittir, çünkü medyan bir olasılıktır'], 'Binom dağılımında medyan ⌊np⌋ ya da ⌈np⌉ değerlerinden biridir; örneğin Binom(10; 0,3) için medyan 3\'tür.'),
  ('Aşağıdaki dağılımlardan hangisi kesikli bir olasılık dağılımıdır?', 'Poisson dağılımı', ['Normal dağılım', 'Üstel dağılım', 'Ki-kare dağılımı'], 'Poisson yalnız 0, 1, 2, … gibi sayılabilir değerler alır; normal, üstel ve ki-kare dağılımları bir aralıktaki her gerçek değeri alabilen sürekli dağılımlardır.'),
  ('Binom dağılımı yazılırken p başarı olasılığını gösterdiğinde q harfi genellikle neyi gösterir?', 'Başarısızlık olasılığını, yani 1 − p\'yi', ['Deneme sayısını', 'Başarı sayısını', 'Beklenen değerin varyansa oranını'], 'İki sonuçlu denemede olasılıklar toplamı 1 olduğundan başarısızlık olasılığı q = 1 − p\'dir; varyans da npq biçiminde yazılır.'),
  ('Hipergeometrik dağılımı belirleyen üç parametre hangileridir?', 'Topluluk büyüklüğü N, topluluktaki başarı sayısı K ve çekiliş sayısı n', ['Ortalama, varyans ve çarpıklık', 'Deneme sayısı n, başarı olasılığı p ve başarı sayısı k', 'Oran λ, süre t ve olay sayısı k'], 'Hipergeometrik dağılım sonlu bir topluluktan geri koymadan seçimi modeller; bu yüzden topluluğun büyüklüğü, içindeki başarı sayısı ve kaç birim çekildiği bilinmelidir.'),
  ('Poisson dağılımında λ büyüdükçe hiç olay gerçekleşmeme olasılığı P(X = 0) nasıl değişir?', 'Azalır', ['Artar', 'Değişmez', 'Önce artar, sonra azalır'], 'P(X = 0) = e^(−λ) azalan bir fonksiyondur; ortalama olay sayısı arttıkça hiç olay olmaması daha az olası hâle gelir.'),
  ('Bir kentte ocak ayının günlük en düşük sıcaklıkları N(−5 °C; σ = 3 °C) ile modelleniyor. Bu modelle ilgili hangisi doğrudur?', 'Normal dağılımın ortalaması negatif olabilir; model geçerlidir', ['Normal dağılımın ortalaması negatif olamaz', 'Standart sapma ortalamadan büyük olmalıdır', 'Sıcaklık sayılabilir bir nicelik olduğu için Poisson modeli kullanılmalıdır'], 'μ herhangi bir gerçek sayı olabilir; yalnız σ pozitif olmalıdır. Sıcaklık sürekli ve negatif değer alabilen bir nicelik olduğundan normal model uygundur.'),
  ('Ki-kare dağılımına uyan bir değişken hangi değerleri alabilir?', 'Yalnızca negatif olmayan değerleri', ['Bütün gerçek sayıları', 'Yalnızca tam sayıları', 'Yalnızca −1 ile 1 arasındaki değerleri'], 'Ki-kare değişkeni normal değişkenlerin kareleri toplamı olduğundan sıfırdan küçük olamaz; dağılımı sağa çarpıktır.'),
  ('Multinom dağılımında kategori sayısı 2 olursa hangi dağılım elde edilir?', 'Binom dağılımı', ['Poisson dağılımı', 'Geometrik dağılım', 'Normal dağılım'], 'İki kategori \'başarı\' ve \'başarısızlık\' olarak düşünülebilir; bu durumda birinci kategorinin sayısı Binom(n, p) dağılır.'),
  ('Ortalaması 2 dakika olan üstel dağılımlı bir bekleme süresinin yoğunluk fonksiyonu f(t) = λe^(−λt) biçimindedir. f(0) değeri kaçtır?', '0,5 (dakika başına)', ['2 (dakika başına)', '1', '0'], 'λ = 1/ortalama = 0,5\'tir ve f(0) = λ = 0,5 olur. Bu bir olasılık değil, birim süre başına yoğunluktur.'),
  ('Bir fabrika binom modelinde \'başarı\' olarak \'ürünün kusurlu çıkmasını\' tanımlıyor. Bu tanım hakkında hangisi doğrudur?', 'Uygundur; \'başarı\' yalnız ilgilenilen sonucu belirten bir addır', ['Yanlıştır; başarı her zaman olumlu bir sonuç olmalıdır', 'Yanlıştır; kusurlu ürün sayısı binomla modellenemez', 'Uygundur, ama bu durumda başarı olasılığı p her zaman 0,5 alınmalıdır'], 'Binom dilinde \'başarı\', sayılan olayın adıdır; kusurlu ürün, hastalık ya da kaza gibi istenmeyen bir sonuç da olabilir.'),
  ('Poisson olasılık formülünde yer alan matematiksel sabit hangisidir?', 'e (Euler sayısı, ≈ 2,718)', ['π (≈ 3,14)', 'Altın oran (≈ 1,618)', '√2 (≈ 1,4142)'], 'P(X = k) = e^(−λ)λᵏ/k! formülünde e sabiti bulunur; normal yoğunluk ise hem e\'yi hem π\'yi içerir.'),
  ('Normal dağılımın yoğunluk formülünde hangi iki matematiksel sabit birlikte yer alır?', 'π ve e', ['π ve altın oran', 'e ve √3', 'Yalnız π'], 'f(x) = e^(−(x − μ)²/(2σ²))/(σ√(2π)) formülünde hem e hem π bulunur.'),
  ('Hilesiz bir para 10 kez atıldığında yazı sayısı için en düşük olasılıklı değerler hangileridir?', '0 ve 10', ['5', '4 ve 6', '1 ve 9'], 'P(0) = P(10) = 1/1024 en küçük olasılıklardır; olasılıklar ortaya (5\'e) doğru artar.'),
  ('Bir Poisson dağılımında λ değeri 2\'den 10\'a çıkarıldığında olasılık grafiği nasıl değişir?', 'Sağa kayar ve yayılır', ['Sola kayar ve daralır', 'Hiç değişmez', 'Yalnız 0 değerinde yükselir'], 'Ortalama λ büyüdükçe olasılıklar daha büyük değerlerde toplanır; varyans da λ olduğundan dağılım genişler.'),
  ('Hipergeometrik dağılımda yalnız bir birim çekilirse (n = 1) başarı sayısı hangi dağılıma uyar?', 'Başarı olasılığı K/N olan Bernoulli dağılımına', ['Poisson(K/N) dağılımına', 'Binom(N, K) dağılımına', 'Geometrik(K/N) dağılımına'], 'Tek çekilişte geri koyma sorunu ortaya çıkmaz; çekilen birimin başarı olma olasılığı K/N\'dir ve sonuç 0 ya da 1\'dir.'),
  ('Ayşe bir sınavda 90. yüzdelikte, Can ise normal dağılan başka bir sınavda z = 1,5 puanla yer alıyor. Φ(1,5) ≈ 0,933 olduğuna göre kendi gruplarına göre hangisinin konumu daha yüksektir?', 'Can\'ın', ['Ayşe\'nin', 'İkisi eşittir', 'Karşılaştırılamaz'], 'z = 1,5 yaklaşık 93. yüzdeliğe karşılık gelir; bu Ayşe\'nin 90. yüzdeliğinden yüksektir.'),
  ('Başarı olasılığı 0,5 olan bağımsız denemelerde 3. başarının tam 3. denemede gelme olasılığı kaçtır?', '1/8', ['3/8', '1/2', '1/16'], '3. başarı 3. denemede geliyorsa ilk üç denemenin hepsi başarılıdır: 0,5³ = 1/8.'),
  ('15 parçalık bir partide 3 kusurlu var; rastgele ve geri konmadan 5 parça seçiliyor. Seçilen kusurlu sayısının alabileceği en büyük değer kaçtır?', '3', ['5', '15', '2'], 'Seçimde en çok partideki kusurlu sayısı kadar kusurlu çıkabilir: min(n, K) = min(5, 3) = 3.'),
  ('Bir Bernoulli değişkeninin varyansı p(1 − p)\'dir. Bu varyans hangi p değerlerinde sıfır olur?', 'p = 0 ve p = 1', ['Yalnız p = 0,5', 'p = 0,25 ve p = 0,75', 'Hiçbir p değerinde'], 'p = 0 ya da 1 iken sonuç kesindir, değişkenlik yoktur; varyans 0 olur. En büyük değerini ise p = 0,5\'te alır.'),
  ('Görüntü ve sinyal işlemede ortalaması sıfır, normal dağılımlı rastgele bozulmalara genellikle ne ad verilir?', 'Gauss gürültüsü', ['Poisson kuyruğu', 'Bernoulli kayması', 'Binom saçılması'], 'Normal dağılım Gauss\'un adıyla da anıldığından, birçok küçük bağımsız etkinin toplamı olan bu tür bozulmalar \'Gauss gürültüsü\' olarak adlandırılır.'),
  ('Normal dağılan bir değişkende değerlerin ortalamanın 1 standart sapma üstünden büyük olma olasılığı yaklaşık 0,16\'dır. Bağımsız iki gözlemin ikisinin de bu sınırı aşma olasılığı yaklaşık kaçtır?', '0,025', ['0,16', '0,32', '0,0800'], 'Bağımsız olaylarda olasılıklar çarpılır: 0,16² ≈ 0,025.'),
  ('Bir değişkenin dağılımı Poisson(λ) iken gözlem süresi iki katına çıkarılıp ölçek değiştirilmeden sayım yapılırsa yayılım indeksi (varyans/ortalama) kaç olur?', 'Yine 1', ['2', '1/2', '4, çünkü varyans karesel büyür'], 'Yeni süre için sayım Poisson(2λ) dağılır; ortalama da varyans da 2λ olduğundan oran yine 1\'dir.'),
  ('Kabul örneklemesinde \'kabul edilebilir kalite düzeyi\' (AQL) neyi ifade eder?', 'Süreç ortalaması olarak tatmin edici sayılan en yüksek kusur oranını', ['Hiç kusur bulunmayan partilerin oranını', 'Muayene edilen örneklemin büyüklüğünü', 'Reddedilen partilerin yeniden işlenmesi için katlanılan toplam maliyeti'], 'AQL düzeyindeki partilerin yüksek olasılıkla (örneğin %95) kabul edilmesi hedeflenir; üretici riski bu kalite düzeyinde tanımlanır.'),
  ('Arızaları sabit hızla oluşan (üstel ömürlü) bir cihaz için verilen \'arızalar arası ortalama süre\' (MTBF) değeri, üstel dağılımın hangi niceliğine karşılık gelir?', 'Ortalamaya, yani 1/λ\'ya', ['Medyana, yani ln 2/λ\'ya', 'Varyansa, yani 1/λ²\'ye', 'Arıza oranının kendisine, yani λ\'ya'], 'MTBF, ardışık arızalar arasındaki beklenen süredir; üstel modelde bu 1/λ\'dır. Örneğin λ = 0,001/saat ise MTBF 1000 saattir.'),
  ('6 denemeli bir binom deneyinde beklenen başarı sayısı 3\'tür. Hiç başarı olmama olasılığı kaçtır?', '1/64', ['1/6', '1/32', '1/2'], 'p = 3/6 = 1/2 bulunur; P(X = 0) = (1/2)⁶ = 1/64.'),
  ('4 seçenekli 10 soruluk bir testte bir öğrenci her soruda 2 yanlış seçeneği eleyip kalan ikisinden birini rastgele seçiyor. Beklenen doğru sayısı, hiç eleme yapmadan rastgele işaretlemeye göre nasıl değişir?', '2,5\'ten 5\'e çıkar', ['2,5\'te kalır', '4\'ten 5\'e çıkar', '5\'ten 7,5\'e çıkar'], 'Eleme olmadan p = 1/4 ve E = 2,5\'tir; iki seçenek elenince p = 1/2 ve E = 10 · 0,5 = 5 olur.'),
  ('Negatif binom dağılımında hedeflenen başarı sayısı r = 1 alınırsa hangi dağılım elde edilir?', 'Geometrik dağılım', ['Bernoulli dağılımı', 'Poisson dağılımı', 'Hipergeometrik dağılım'], 'İlk başarıya kadar geçen deneme sayısı, negatif binomun r = 1 özel durumudur.'),
  ('Gamma dağılımında biçim parametresi k = 1 alınırsa hangi dağılım elde edilir?', 'Üstel dağılım', ['Normal dağılım', 'Poisson dağılımı', 'Ki-kare dağılımı'], 'Gamma(1, θ) yoğunluğu (1/θ)e^(−x/θ) olup ortalaması θ olan üstel dağılımdır; Poisson sürecinde ilk olaya kadarki süre de budur.'),
  ('Serbestlik derecesi çok büyük olan bir ki-kare dağılımının biçimi hangi dağılıma yaklaşır?', 'Normal dağılıma', ['Üstel dağılıma', 'Poisson dağılımına', 'Sürekli düzgün dağılıma'], 'χ²(k), k bağımsız karenin toplamı olduğundan merkezî limit teoremi gereği k büyüdükçe ortalaması k, varyansı 2k olan normale yaklaşır.'),
  ('Normal dağılan bir değişkende birinci çeyrek ile medyan arasındaki uzaklık, medyan ile üçüncü çeyrek arasındaki uzaklıkla nasıl karşılaştırılır?', 'Eşittir', ['Birincisi daha büyüktür', 'İkincisi daha büyüktür', 'Standart sapmaya göre değişir'], 'Normal dağılım simetrik olduğundan Q1 = μ − 0,674σ ve Q3 = μ + 0,674σ medyana eşit uzaklıktadır; kutu grafiğinde medyan çizgisi kutunun ortasında olur.'),
  ('Kesikli değişkenler için olasılık kütle fonksiyonu kullanılırken sürekli değişkenler için hangi kavram kullanılır?', 'Olasılık yoğunluk fonksiyonu', ['Olasılık üreten fonksiyon', 'Hayatta kalma fonksiyonu', 'Olabilirlik fonksiyonu ve onun logaritması'], 'Sürekli değişkenlerde tek tek değerlerin olasılığı sıfırdır; olasılıklar yoğunluk fonksiyonunun altındaki alanla bulunur.'),
  ('Birikimli dağılım fonksiyonunun tersi olan ve verilen bir olasılık için ilgili yüzdelik değeri döndüren fonksiyona ne ad verilir?', 'Nicelik (kantil) fonksiyonu', ['Moment üreten fonksiyon', 'Olasılık kütle fonksiyonu', 'Tehlike (arıza oranı) fonksiyonu ya da risk fonksiyonu'], 'Q(p) = F⁻¹(p) biçimindeki nicelik fonksiyonu, örneğin standart normalde Q(0,975) ≈ 1,96 değerini verir.'),
  ('Bir rastgele değişkenin pozitif olasılık (ya da yoğunluk) taşıdığı değerler kümesine ne ad verilir? Örneğin Poisson için bu küme {0, 1, 2, …}\'dir.', 'Dağılımın desteği', ['Dağılımın modu', 'Dağılımın varyansı', 'Dağılımın parametresi'], 'Destek, değişkenin alabileceği değerlerin kümesidir; binomda {0, …, n}, üstelde [0, ∞), normalde tüm gerçek sayılardır.'),
  ('R programlama dilinde dağılım fonksiyonlarının önekleri (d, p, q, r) bir düzen izler. \'pnorm(1,96)\' komutu neyi döndürür?', 'Standart normalde 1,96\'nın solundaki alanı', ['1,96 noktasındaki yoğunluk eğrisinin yüksekliğini', '0,975\'e karşılık gelen z değerini', '1,96 ortalamalı rastgele bir sayıyı'], 'R\'da d yoğunluk/kütle, p birikimli olasılık, q nicelik (ters), r rastgele sayı üretimi içindir; pnorm(1,96) ≈ 0,975 verir.'),
  ('İstatistik yazımında \'X ~ Poisson(3)\' ifadesindeki \'~\' işareti nasıl okunur?', 'X, Poisson(3) dağılımına uyar', ['X yaklaşık olarak 3\'e eşittir', 'X, 3\'ün Poisson katıdır', 'X ile 3 arasında korelasyon vardır'], '\'~\' işareti \'dağılımına uyar\' anlamındadır. Yaklaşık eşitlik için \'≈\' kullanılır.'),
  ('Olasılıkta sık geçen \'iid\' kısaltması değişkenler için neyi belirtir?', 'Bağımsız ve aynı dağılımlı olduklarını', ['Ortalamalarının sıfır olduğunu', 'Normal dağıldıklarını', 'Birbirleriyle güçlü biçimde ilişkili olduklarını'], 'iid (independent and identically distributed), değişkenlerin birbirini etkilemediğini ve hepsinin aynı dağılıma sahip olduğunu anlatır; binom ve merkezî limit teoremi bu varsayıma dayanır.'),
  ('Poisson sürecinde λ (olay hızı) arttıkça olaylar arasındaki bekleme süreleri nasıl değişir?', 'Ortalamaları 1/λ olduğundan kısalır', ['Uzar', 'Değişmez', 'Rastgelelikleri tamamen ortadan kalkar'], 'Olaylar arası süreler oranı λ olan üstel dağılımlıdır; ortalama 1/λ, λ büyüdükçe küçülür.'),
  ('Bir sınıfta notlar N(65; σ = 10) dağılıyor. 30 öğrencilik bir sınıfta 75\'in üstünde not alması beklenen öğrenci sayısı yaklaşık kaçtır? (Φ(1) ≈ 0,84)', '5', ['10', '3', '16'], 'P(X > 75) = 1 − Φ(1) ≈ 0,16; 30 · 0,16 ≈ 4,8, yani yaklaşık 5 öğrenci beklenir.'),
  ('İki denemeli bir binom deneyinde hiç başarı olmama olasılığı 0,25\'tir. Tam bir başarı olma olasılığı kaçtır?', '0,5', ['0,25', '0,75', '0,375'], '(1 − p)² = 0,25 ise p = 0,5\'tir; P(X = 1) = 2 · 0,5 · 0,5 = 0,5.'),
  ('Bir gazete \'Bu yıl doğan bebeklerin yarısı ortalamanın üstünde kiloyla doğdu\' başlığını şaşırtıcı bir haber gibi veriyor. Doğum kiloları yaklaşık normal dağılıyorsa bu başlık hakkında ne söylenebilir?', 'Beklenen bir durumdur; simetrik dağılımda değerlerin yarısı ortalamanın üstündedir', ['Bir sağlık sorununa işaret eder', 'İmkânsızdır; normal dağılımda ortalamanın üstünde kalanların oranı yalnız %16 civarındadır', 'Ortalamanın yanlış hesaplandığını gösterir'], 'Normal dağılımda ortalama aynı zamanda medyandır; değerlerin yaklaşık yarısının ortalamanın üstünde olması doğal bir sonuçtur.'),
  ('Penaltı başarısı %80 olan bir futbolcu \'Beş penaltıdan dördünü kesin atarım, çünkü 5\'in %80\'i 4\'tür\' diyor. Atışlar bağımsızsa tam 4 penaltıyı atma olasılığı yaklaşık kaçtır?', '0,41', ['0,80', '1,00', '0,33'], 'P(X = 4) = 5 · 0,8⁴ · 0,2 ≈ 0,41\'dir. Beklenen değer 4 olsa da tam 4 gol olasılığı yarının altındadır.'),
  ('p sabitken binom dağılımında deneme sayısı n artırılırsa olasılık grafiği (histogram) nasıl değişir?', 'Tepe noktası sağa kayar ve dağılım genişler', ['Tepe noktası sola kayar ve daralır', 'Hiç değişmez', 'Bütün olasılıklar birbirine eşitlenir ve grafik düzleşir'], 'Ortalama np ve varyans np(1 − p) n ile artar; grafik sağa kayar, yayılır ve giderek çan biçimine yaklaşır.'),
  ('Binom dağılımı p > 0,5 için sola çarpık olabilir. Poisson dağılımı için çarpıklık yönü hakkında hangisi doğrudur?', 'Her λ için sağa çarpıktır; sola çarpık olamaz', ['λ > 5 için sola çarpıktır', 'λ tam sayıysa tam simetriktir', 'Çarpıklık yönü λ\'nın işaretine bağlıdır, negatif λ için sola çarpıktır'], 'Poisson\'un çarpıklığı 1/√λ her zaman pozitiftir; λ büyüdükçe sıfıra yaklaşır ama negatif olmaz.'),
  ('Bir mühendis \'Arıza sayıları Poisson dağılıyor, öyleyse iki arıza arasındaki süreler de Poisson dağılır\' diyor. Bu ifadenin doğrusu hangisidir?', 'Arızalar arası süreler üstel dağılır', ['Arızalar arası süreler de Poisson dağılır', 'Arızalar arası süreler normal dağılır', 'Arızalar arası süreler sabittir'], 'Poisson sürecinde belirli bir sürede gözlenen sayı Poisson, olaylar arasındaki süreler ise sürekli ve üstel dağılımlıdır.'),
  ('Hilesiz bir para beş kez atılıyor. Bir öğrenci beklenen yazı sayısı 2,5 olduğu için \'2,5 yazı gelme olasılığını\' hesaplamak istiyor. Bu olasılık kaçtır?', '0', ['0,3125', '0,5', '0,15625'], 'Binom değişkeni yalnız 0, 1, …, 5 tam sayı değerlerini alır; 2,5 olası bir değer değildir. Beklenen değerin 2,5 olması bu değerin gözlenebileceği anlamına gelmez.'),
  ('Poisson dağılımı için aşağıdakilerden hangisi yanlıştır?', 'Varyansı her zaman ortalamasından büyüktür', ['Negatif olmayan tam sayı değerleri alır', 'Ortalaması λ\'dır', 'Bağımsız iki Poisson değişkeninin toplamı Poisson dağılır'], 'Poisson\'da varyans ortalamaya eşittir; varyansın ortalamadan büyük olması aşırı yayılım demektir ve Poisson\'un özelliği değildir.'),
  ('Sabit sayıda denemedeki başarıları sayan dağılımla ilgili aşağıdaki ifadelerden hangisi yanlıştır?', 'Deneme sayısı rastgele bir değişkendir', ['Denemeler birbirinden bağımsızdır', 'Her denemede başarı olasılığı aynıdır', 'Başarı sayısı 0 ile n arasında tam sayıdır'], 'Binomda deneme sayısı n önceden sabitlenir; rastgele olan başarı sayısıdır. Deneme sayısının rastgele olduğu durumlar geometrik ya da negatif binomla modellenir.'),
  ('Üstel dağılım için aşağıdakilerden hangisi yanlıştır?', 'Ortalamasına göre simetriktir', ['Yalnız negatif olmayan değerler alır', 'Belleksizlik özelliğine sahiptir', 'Standart sapması ortalamasına eşittir'], 'Üstel dağılım sıfırda en yüksek yoğunluğa sahip ve sağa çarpıktır; ortalaması medyanından büyüktür, dolayısıyla simetrik değildir.'),
  ('Ortalaması sıfır olan normal dağılımlı bir ölçüm hatası X\'in işareti değiştirilerek −X elde ediliyor. −X hangi dağılıma uyar?', 'X ile aynıdır, N(0; σ²)', ['N(0; −σ²)', 'N(−σ; σ²), çünkü işaret ortalamaya geçer', 'Standart normal'], 'Ortalaması 0 olan normal dağılım sıfıra göre simetriktir; işaret değiştirmek ortalamayı 0\'da, varyansı (−1)²σ² = σ²\'de bırakır.'),
  ('Erlang (gamma) dağılımında biçim parametresi k büyüdükçe dağılımın biçimi nasıl değişir?', 'Çarpıklık azalır ve dağılım normale benzer', ['Daha çarpık hâle gelir', 'Üstel dağılıma yaklaşır', 'Düzgün dağılıma dönüşür ve bütün değerler eşit olasılıklı olur'], 'Erlang(k) k bağımsız üstelin toplamı olduğundan çarpıklığı 2/√k\'dir; k büyüdükçe merkezî limit etkisiyle simetrikleşir.'),
  ('Normal dağılımda ortalamanın ±kσ aralığına düşme olasılığı k büyüdükçe nasıl davranır?', 'Artar ve 1\'e yaklaşır ama hiçbir sonlu k için 1\'e ulaşmaz', ['k = 3\'te tam 1 olur', 'k arttıkça azalır', 'Her k için %68\'dir'], '2Φ(k) − 1, k ile artar; k = 3\'te ≈ 0,9973, k = 6\'da ≈ 0,999999998\'dir. Normal dağılımın kuyrukları sonsuza uzandığından olasılık hiçbir zaman tam 1 olmaz.'),
];
